# 模拟动态分区插入: PARTITION 列的值从 SELECT 的动态列取得, 而非写死
source = [
    ("2024-01-01", "a", 1), ("2024-01-01", "b", 2),
    ("2024-01-02", "c", 3), ("2024-01-02", "d", 4),
    ("2024-01-03", "e", 5),
]
static_result = {}
for dt, k, v in source:
    static_result.setdefault(dt, []).append((k, v))
print("源数据含 dt 取值:", sorted(set(r[0] for r in source)))
print("若用静态分区, 需为 3 个 dt 各写 1 条 INSERT OVERWRITE ... PARTITION(dt='...')\n")

# 动态分区: 一条语句, 最后一个 SELECT 列为分区值
dynamic_result = {}
for dt, k, v in source:
    dynamic_result.setdefault(dt, []).append((k, v))
print("动态分区: INSERT OVERWRITE TABLE target PARTITION(dt) SELECT k, v, dt FROM source")
print("=> 自动按 SELECT 末尾列 dt 的取值创建分区:")
for dt in sorted(dynamic_result):
    print(f"   PARTITION(dt='{dt}') 写入 {len(dynamic_result[dt])} 行: {dynamic_result[dt]}")
print("\n对比: 动态分区省去手写多分区, 但会写大量分区(需 hive.exec.dynamic.partition.mode=nonstrict 防误写全表)")
